#!/usr/bin/env node

/**
 * Exercises check-openapi-fresh.mjs against fixture repositories.
 *
 * Each fixture is a real git repository laid out like this one —
 * `packages/api/openapi.json` beside `packages/api/scripts/generate-openapi.ts`
 * — because the check compares regenerated bytes against committed ones, which
 * is also what a CI checkout gives it. The fixture generator is a stub with a
 * `MOUNT_MAP` of its own, so an entry can be REMOVED from it and the gate's
 * verdict observed. Offline: the stub imports nothing but `node:fs`.
 *
 * `map-entry-dropped` and `expected-path-dropped` are the cases that matter
 * most, and they are the POSITIVE CONTROL for the whole design. In both, the
 * committed document is byte-identical to what the generator produces, so the
 * regenerate-and-diff layer is GREEN — which is precisely the state the real
 * defect shipped in. Only the by-name layer sees them, and if that layer is ever
 * removed these two cases pass and nothing anywhere goes red.
 *
 * `expected-list-shrunk` mutates a COPY of the gate itself, because a floor
 * whose violation is unreachable from any fixture is a floor nobody has watched
 * fail.
 *
 * Fixtures are created under the OS temp dir. Point TMPDIR at a filesystem with
 * room if the default is a small tmpfs.
 */

import { execFileSync } from 'node:child_process';
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const scriptsDir = dirname(fileURLToPath(import.meta.url));
const checkScript = resolve(scriptsDir, 'check-openapi-fresh.mjs');
const fixturePrefix = join(tmpdir(), 'oxy-openapi-fresh-');
const createdFixtures = [];
const failures = [];

/**
 * The route table the stub generator emits from, keyed the way the real
 * `MOUNT_MAP` is keyed. Deliberately only the inference files: the gate says
 * nothing about the rest of the API, so a fixture carrying it would be scenery.
 */
const FIXTURE_ROUTES = {
  'inferenceEdge.ts': [
    ['post', '/responses'],
    ['post', '/chat/completions'],
    ['get', '/generations/{id}'],
  ],
  'inferenceCatalogue.ts': [
    ['get', '/'],
    ['get', '/stats'],
    ['get', '/routing-profiles'],
    ['get', '/{publisher}/{model}'],
  ],
  'inferenceAdmin.ts': [['get', '/rollout']],
  'inferenceRoutingPolicies.ts': [['get', '/accounts/{accountId}']],
  'inferenceProviderConnections.ts': [['get', '/accounts/{accountId}']],
  'inferenceReporting.ts': [['get', '/accounts/{accountId}/balance']],
};

const FIXTURE_MAP = {
  'inferenceEdge.ts': ['/v1'],
  'inferenceCatalogue.ts': ['/v1/models', '/models'],
  'inferenceAdmin.ts': ['/inference/admin'],
  'inferenceRoutingPolicies.ts': ['/inference/routing-policies'],
  'inferenceProviderConnections.ts': ['/inference/provider-connections'],
  'inferenceReporting.ts': ['/inference/reporting'],
};

function runCommand(command, args, cwd, extraEnvironment = {}) {
  try {
    const stdout = execFileSync(command, args, {
      cwd,
      encoding: 'utf8',
      env: { ...process.env, ...extraEnvironment },
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    return { code: 0, output: stdout };
  } catch (error) {
    return { code: error.status ?? 1, output: `${error.stdout ?? ''}${error.stderr ?? ''}` };
  }
}

/**
 * A stub generator carrying its own mount map, so the gate can be shown what it
 * does when the map loses an entry. `securityOverrides` lets a fixture publish an
 * operation as anonymous without hand-writing a whole document.
 */
function generatorSource(mountMap, securityOverrides) {
  return `import { writeFileSync } from 'node:fs';

const MOUNT_MAP = ${JSON.stringify(mountMap, null, 2)};
const ROUTES = ${JSON.stringify(FIXTURE_ROUTES, null, 2)};
const SECURITY_OVERRIDES = ${JSON.stringify(securityOverrides, null, 2)};
const CREDENTIALLED = [{ bearerAuth: [] }];
const ANONYMOUS = [{}];

const paths = {};
for (const [file, prefixes] of Object.entries(MOUNT_MAP)) {
  for (const prefix of prefixes) {
    for (const [verb, suffix] of ROUTES[file] ?? []) {
      const full = (suffix === '/' ? prefix : prefix + suffix).replace(/\\/+/g, '/');
      const isCatalogue = full === '/models' || full === '/v1/models' ||
        full.startsWith('/models/') || full.startsWith('/v1/models/');
      const security = Object.hasOwn(SECURITY_OVERRIDES, full + ' ' + verb)
        ? SECURITY_OVERRIDES[full + ' ' + verb]
        : isCatalogue ? ANONYMOUS : CREDENTIALLED;
      paths[full] = { ...(paths[full] ?? {}), [verb]: security === null ? {} : { security } };
    }
  }
}

writeFileSync(
  new URL('../openapi.json', import.meta.url),
  JSON.stringify({ openapi: '3.1.0', info: { title: 'fixture', version: '0' }, paths }, null, 2) + '\\n',
);
`;
}

/**
 * Build a fixture repository, generate its document, and commit it. The result is
 * the state a CI checkout starts from: a committed artifact and the generator
 * that produced it.
 */
function createFixture({ mountMap = FIXTURE_MAP, securityOverrides = {} } = {}) {
  const root = mkdtempSync(fixturePrefix);
  createdFixtures.push(root);
  mkdirSync(join(root, 'packages', 'api', 'scripts'), { recursive: true });
  writeFileSync(
    join(root, 'packages', 'api', 'scripts', 'generate-openapi.ts'),
    generatorSource(mountMap, securityOverrides),
  );

  const generate = runCommand('bun', ['packages/api/scripts/generate-openapi.ts'], root);
  if (generate.code !== 0) throw new Error(`Fixture generate failed: ${generate.output}`);

  for (const args of [
    ['init', '-q', '.'],
    ['add', '-A'],
    ['-c', 'user.email=fixture@example.invalid', '-c', 'user.name=fixture', 'commit', '-qm', 'fixture'],
  ]) {
    const step = runCommand('git', args, root);
    if (step.code !== 0) throw new Error(`Fixture git ${args[0]} failed: ${step.output}`);
  }
  return root;
}

function commitAll(root) {
  for (const args of [
    ['add', '-A'],
    ['-c', 'user.email=fixture@example.invalid', '-c', 'user.name=fixture', 'commit', '-qm', 'edit'],
  ]) {
    const step = runCommand('git', args, root);
    if (step.code !== 0) throw new Error(`Fixture git ${args[0]} failed: ${step.output}`);
  }
}

function expectVerdict(caseName, root, expectedCode, expectedFragment, script = checkScript) {
  const { code, output } = runCommand('bun', [script], root);
  if (code !== expectedCode) {
    failures.push(`${caseName}: expected exit ${expectedCode}, got ${code}.\n${output}`);
    return;
  }
  if (!output.includes(expectedFragment)) {
    failures.push(`${caseName}: output does not contain ${JSON.stringify(expectedFragment)}.\n${output}`);
  }
}

// A complete, fresh document must pass, or nothing below means anything.
expectVerdict('complete', createFixture(), 0, 'is fresh, describes 11 named inference path(s)');

// POSITIVE CONTROL. A whole route file dropped from the map, with the artifact
// regenerated in the same commit — so the freshness layer is green and only the
// by-name layer can see it.
const droppedPrefixMap = { ...FIXTURE_MAP };
delete droppedPrefixMap['inferenceAdmin.ts'];
expectVerdict(
  'map-entry-dropped',
  createFixture({ mountMap: droppedPrefixMap }),
  1,
  'no path under /inference/admin/ is described',
);

// The same failure on the customer-facing edge, where the loss is named rather
// than counted.
const droppedEdgeMap = { ...FIXTURE_MAP };
delete droppedEdgeMap['inferenceEdge.ts'];
expectVerdict(
  'expected-path-dropped',
  createFixture({ mountMap: droppedEdgeMap }),
  1,
  '/v1/chat/completions is not described at all.',
);

// The catalogue is mounted TWICE. A map that keeps only one prefix leaves a
// document that looks complete unless both are named.
expectVerdict(
  'second-mount-dropped',
  createFixture({ mountMap: { ...FIXTURE_MAP, 'inferenceCatalogue.ts': ['/v1/models'] } }),
  1,
  '/models/stats is not described at all.',
);

// An unrecognised gate makes the generator publish an operation as public.
expectVerdict(
  'edge-published-as-public',
  createFixture({ securityOverrides: { '/v1/chat/completions post': [{}] } }),
  1,
  'POST /v1/chat/completions offers an EMPTY security requirement',
);

// The same defect one step further along: no `security` key at all.
expectVerdict(
  'edge-published-with-no-security',
  createFixture({ securityOverrides: { '/v1/responses post': null } }),
  1,
  'POST /v1/responses publishes no `security` at all',
);

// A route added without regenerating: complete and correctly gated, but not what
// the generator now produces.
const staleFixture = createFixture();
const staleDocument = JSON.parse(readFileSync(join(staleFixture, 'packages/api/openapi.json'), 'utf8'));
staleDocument.paths['/unrelated'] = { get: { security: [{}] } };
writeFileSync(
  join(staleFixture, 'packages/api/openapi.json'),
  `${JSON.stringify(staleDocument, null, 2)}\n`,
);
commitAll(staleFixture);
expectVerdict('stale-artifact', staleFixture, 1, '/unrelated is in the committed document but no longer served.');

// An already-modified document makes attribution impossible, so the gate must
// refuse rather than blame the commit for what was altered beforehand.
const dirtyFixture = createFixture();
writeFileSync(
  join(dirtyFixture, 'packages/api/openapi.json'),
  `${readFileSync(join(dirtyFixture, 'packages/api/openapi.json'), 'utf8')}\n`,
);
expectVerdict('dirty-document', dirtyFixture, 1, 'already has uncommitted changes');

// MUTATION TEST of the vacuity floor. Layer 1 guarantees the credential rule
// always examines at least its floor, so the only way to watch a floor fail is to
// weaken the gate itself — which is also the change a future edit would make.
const mutatedScript = join(mkdtempSync(fixturePrefix), 'check-openapi-fresh.mjs');
createdFixtures.push(dirname(mutatedScript));
const gateSource = readFileSync(checkScript, 'utf8');
const mutatedSource = gateSource.replace("  '/v1/responses',\n", '');
if (mutatedSource === gateSource) {
  failures.push('expected-list-shrunk: the mutation did not apply, so the case would prove nothing.');
} else {
  writeFileSync(mutatedScript, mutatedSource);
  expectVerdict(
    'expected-list-shrunk',
    createFixture(),
    1,
    'below the floor of 11',
    mutatedScript,
  );
}

for (const fixture of createdFixtures) {
  if (fixture.startsWith(fixturePrefix)) rmSync(fixture, { recursive: true, force: true });
}

if (failures.length > 0) {
  console.error('OpenAPI freshness check tests failed:\n');
  for (const failure of failures) console.error(`- ${failure}`);
  process.exit(1);
}

console.log(`OpenAPI freshness check discriminated ${createdFixtures.length - 1} fixture case(s).`);
